INSERT INTO "pieces" ("id","slug","name","subtitle","collection_id","description","sort_order","featured","published","deleted_at","created_at","updated_at","created_by","updated_by") VALUES('192b3688-d2ca-47a5-8916-2862513a8328','13','Panna Vriksh','Where Enamel Meets Antiquity','bracelets-and-bangles',replace('Panna Vriksh is a wide, sculptural kada built for presence. A ribbed gold surface runs the width of the band, bordered top and bottom by a fine, continuous Greek-key engraving that frames the piece like a picture within a picture. At its centre, a meenakari leaf motif in emerald green and cobalt blue climbs upward from a scrolling gold vine, its enamel work adding rare colour against the warmth of the gold. The bangle culminates at each end in a raised floral bloom, echoing traditional temple-jewellery detailing.\n\nSubstantial in weight and scale, it is designed as a statement piece — the kind of bangle passed down through generations, equally suited to bridal wear or festive occasions where its craftsmanship can be seen up close.','\n',char(10)),0,0,1,NULL,'2026-08-24 07:27:37','2026-08-24 18:57:40','35795183-f2f6-4de3-8573-463a9b9718c0','35795183-f2f6-4de3-8573-463a9b9718c0');
