INSERT INTO "pieces" ("id","slug","name","subtitle","collection_id","description","sort_order","featured","published","deleted_at","created_at","updated_at","created_by","updated_by") VALUES('494706fb-9c14-45e9-9742-abcc189bd3fd','19','19','','mens-jewellery','',0,0,0,NULL,'2026-08-24 07:29:45','2026-08-24 07:29:56','35795183-f2f6-4de3-8573-463a9b9718c0','35795183-f2f6-4de3-8573-463a9b9718c0');
INSERT INTO "pieces" ("id","slug","name","subtitle","collection_id","description","sort_order","featured","published","deleted_at","created_at","updated_at","created_by","updated_by") VALUES('bb98d6c7-5ad2-4785-a7d0-d204f128bfe8','20','Argentis','Minimal by Design, Bold by Nature','everyday-jewellery',replace('Argentis moves away from gold into a cooler silver-toned metal, using a compact architectural pendant to create a distinctly modern men''s jewellery piece. The pendant combines polished planes with darker or textured sections, producing contrast through surface treatment rather than coloured gemstones\n\n. The geometry is deliberately strong: straight edges, stepped forms and a compact rectangular centre give the piece a technical, almost industrial character. Any small bright accents are secondary to the metalwork and the contrast between reflective and matte surfaces. \n\nArgentis is designed for a wearer who prefers jewellery with structure rather than ornament. Suspended from a fine silver-toned chain, it has enough presence to stand alone while remaining clean enough to work with casual or tailored clothing. It is a contemporary interpretation of the men''s pendant — architectural, understated and focused on material and form.','\n',char(10)),0,0,1,NULL,'2026-08-24 07:30:19','2026-08-24 18:46:39','35795183-f2f6-4de3-8573-463a9b9718c0','35795183-f2f6-4de3-8573-463a9b9718c0');
INSERT INTO "pieces" ("id","slug","name","subtitle","collection_id","description","sort_order","featured","published","deleted_at","created_at","updated_at","created_by","updated_by") VALUES('7db35e48-6536-46f2-a095-9084a7214ff8','21','Haloire','Simplicity, Encircled','everyday-jewellery',replace('Haloire is a minimalist yellow-gold pendant necklace centred on a clean circular frame. Within the open ring sits a small brilliant diamond accent, creating a concentrated point of white sparkle against the warm gold. The simplicity of the geometry allows the stone to remain visible without the pendant becoming ornate. \n\nThe circular form gives the piece a balanced, contemporary silhouette, while the yellow-gold chain keeps the overall impression warm and refined. The diamond is used as an accent rather than a dominant centre stone, which makes the necklace considerably more versatile than a traditional statement pendant.\n\n Haloire is ideal for everyday luxury: subtle enough for daytime, polished enough for evening, and simple enough to layer with other necklaces. Its appeal comes from the clarity of the design — one clean circle, one bright stone and a fine gold chain working together without unnecessary decoration.','\n',char(10)),0,0,1,NULL,'2026-08-24 07:30:36','2026-08-24 18:45:59','35795183-f2f6-4de3-8573-463a9b9718c0','35795183-f2f6-4de3-8573-463a9b9718c0');
INSERT INTO "pieces" ("id","slug","name","subtitle","collection_id","description","sort_order","featured","published","deleted_at","created_at","updated_at","created_by","updated_by") VALUES('177aa1df-784b-4600-8b5a-50fc3d9de1bf','22','Céleste','A Crescent Caught in Light','everyday-jewellery',replace('Céleste turns a personal initial into a delicate piece of yellow-gold jewellery. The fine chain leads to a stylised letter C, worked with ornamental curves and small decorative details that give the pendant more character than a completely plain initial. \n\nThe warm yellow-gold surface is the dominant feature, catching light along the edges and curves of the letter. Small bright accents add subtle sparkle, but the design remains primarily about the shape of the initial and its personal meaning rather than a heavy diamond display. \n\nThe scale keeps Céleste easy to wear every day. It can sit discreetly at the neckline, become part of a layered chain combination, or serve as a personal signature worn on its own. Its appeal is intimate and uncomplicated: a familiar letter transformed into a polished piece of fine gold jewellery.','\n',char(10)),0,0,1,NULL,'2026-08-24 07:30:54','2026-08-24 18:44:55','35795183-f2f6-4de3-8573-463a9b9718c0','35795183-f2f6-4de3-8573-463a9b9718c0');
INSERT INTO "pieces" ("id","slug","name","subtitle","collection_id","description","sort_order","featured","published","deleted_at","created_at","updated_at","created_by","updated_by") VALUES('a1d69d4d-5ee8-43ce-859b-02103dfdc30d','23','Florenza','Diamonds in Full Bloom','everyday-jewellery',replace('Florenza combines a fine yellow-gold chain with an ornate circular pendant inspired by floral and medallion forms. The pendant has a delicately worked surface, with repeated botanical detailing radiating around the central motif. The warm gold colour gives the piece a distinctly traditional, decorative character.\n\n Because the chain remains fine and understated, the pendant becomes the clear focal point. There is no large gemstone centre; instead, the interest comes from the intricate goldwork and the way its raised details catch the light. The result feels almost like a miniature ornamental plaque suspended at the neckline. \n\nFlorenza is particularly suited to someone who appreciates jewellery with a heritage feel but does not want the scale of a bridal necklace. It works beautifully for festive dressing, cultural occasions or as an elegant everyday pendant when a little more ornament is desired.','\n',char(10)),0,0,1,NULL,'2026-08-24 07:31:12','2026-08-24 18:43:49','35795183-f2f6-4de3-8573-463a9b9718c0','35795183-f2f6-4de3-8573-463a9b9718c0');
INSERT INTO "pieces" ("id","slug","name","subtitle","collection_id","description","sort_order","featured","published","deleted_at","created_at","updated_at","created_by","updated_by") VALUES('ae3cf49d-cb03-4d9a-bc34-adc66f8b5b5c','24','Solenne','Quite Luxury','everyday-jewellery',replace('Solenne is the quietest piece in the collection: a fine yellow-gold chain designed around simplicity, proportion and everyday versatility. Its closely spaced links form a smooth, uninterrupted line around the neck, with the warm gold providing a subtle reflective glow rather than a dramatic statement.\n\n The design does not rely on diamonds or coloured gemstones. Instead, the chain itself is the jewel, allowing the richness of the yellow-gold tone and the precision of the links to remain visible. Its fine scale also makes it particularly useful as a layering foundation for pendants or shorter necklaces.\n\n Solenne is an essential rather than an occasion piece. It can be worn continuously as a refined finishing detail, paired with other gold jewellery or left completely alone. Its strength lies in its restraint: a clean gold line that adds polish without demanding attention.','\n',char(10)),0,0,1,NULL,'2026-08-24 07:31:28','2026-08-24 18:30:00','35795183-f2f6-4de3-8573-463a9b9718c0','35795183-f2f6-4de3-8573-463a9b9718c0');
