INSERT INTO "page_blocks" ("key","value","default_value","label","page","sort_order","updated_at","updated_by") VALUES('home.proof.1.body','Nothing is bought in and rebranded. Design, casting, setting, polishing and finishing all happen in our own workshops.','Nothing is bought in and rebranded. Design, casting, setting, polishing and finishing all happen in our own workshops.','Proof 1 — body','home',3,'2026-08-23 18:40:09',NULL);
