INSERT INTO "timeline_events" ("id","year","title","description","image_id","sort_order","published") VALUES('cf401afb-d281-4f58-9121-ffaef3f26698',1993,'The First Bench','Shri Ashok Kumar Bansal opens a single-bench retail outlet in Malviya Nagar, working alongside his sons and creating jewellery to order for a select handful of families.',NULL,0,1);
INSERT INTO "timeline_events" ("id","year","title","description","image_id","sort_order","published") VALUES('fa8beb7f-a7ad-441e-ba91-ef5da8632669',1999,'Manufacturing Brought Fully In-House','The house strengthens its commitment to craftsmanship by bringing manufacturing fully in-house, with its own manufacturing facility in Mumbai, giving the family greater control over the making, finishing and quality of every piece.',NULL,1,1);
INSERT INTO "timeline_events" ("id","year","title","description","image_id","sort_order","published") VALUES('e056a581-c790-492b-9202-be05aa5104cb',2006,'Expanding Our Presence in the United States','The house extends its presence beyond India, establishing its reach in the United States and building relationships with clients across borders while carrying forward the same standards of trust, craftsmanship and personal service.',NULL,2,1);
INSERT INTO "timeline_events" ("id","year","title","description","image_id","sort_order","published") VALUES('261058c7-6690-4ea1-ac56-5612f2c6ebbe',2011,'A New Chapter','The house continues to grow while remaining firmly rooted in the principles on which it was founded: craftsmanship, integrity, transparency and long-standing relationships.',NULL,3,1);
INSERT INTO "timeline_events" ("id","year","title","description","image_id","sort_order","published") VALUES('2de20920-2154-47a4-940f-5b6448abb198',2021,'The Showroom Is Rebuilt','The showroom is rebuilt with grey Italian marble, black marble walls, nine seating areas and a private cabin — creating a more considered setting for private consultations and bespoke work.',NULL,4,1);
INSERT INTO "timeline_events" ("id","year","title","description","image_id","sort_order","published") VALUES('30213983-c04c-4864-88ca-c82078f8f622',2023,'Thirty Years','Many of the families who came in the first decade now bring their children.',NULL,5,1);
INSERT INTO "process_steps" ("id","sort_order","title","duration","description","image_id","published") VALUES('fcda8b07-4a46-474f-b1f5-0ba882140d37',1,'Consultation','1 hour','We begin by understanding the piece — who it is for, how it will be worn, and what it needs to become. Nothing is shown until we understand that.',NULL,1);
INSERT INTO "process_steps" ("id","sort_order","title","duration","description","image_id","published") VALUES('47b1d8f7-f110-4f4a-801c-82e1b458ccb4',2,'Sketch','1–2 days','The idea is translated onto paper and refined with you. Once the design is agreed upon, we establish the price before any work begins.',NULL,1);
INSERT INTO "process_steps" ("id","sort_order","title","duration","description","image_id","published") VALUES('8685c078-b1d2-40a8-8ad4-bde1919019c4',3,'CAD or Hand-Forming','3–4 days','Depending on the design, the piece is either precisely modelled in CAD or shaped by hand at the bench. Traditional techniques such as polki and jadau are formed by hand, preserving the character of the craft.',NULL,1);
INSERT INTO "process_steps" ("id","sort_order","title","duration","description","image_id","published") VALUES('517a459b-a588-423f-bbd5-91c604e82412',4,'Casting','3–4 days','Where required, the approved design is cast in our own foundry. The metal is carefully measured and recorded before and after casting, keeping the process transparent from the outset.',NULL,1);
INSERT INTO "process_steps" ("id","sort_order","title","duration","description","image_id","published") VALUES('67f46d91-2601-4c07-9a58-591b7af93f01',5,'Stone Setting','1–2 days','Each stone is carefully selected and set by hand. Stones are matched specifically to your piece, with their certificates corresponding to the stones that go into it.',NULL,1);
INSERT INTO "process_steps" ("id","sort_order","title","duration","description","image_id","published") VALUES('9c04cea0-2604-4881-a930-0ea799749057',6,'Polishing','1 day','The piece is finished by hand through a careful polishing process. Every surface and detail is refined before it moves to final inspection.',NULL,1);
INSERT INTO "process_steps" ("id","sort_order","title","duration","description","image_id","published") VALUES('003c72d3-9f39-407c-bf90-7584c9dde4ec',7,'Quality Inspection','1 day','The finished piece is inspected against the approved design, weighed, checked under magnification, hallmarked, and HUID registered. Nothing leaves the bench until it meets our standards.',NULL,1);
INSERT INTO "process_steps" ("id","sort_order","title","duration","description","image_id","published") VALUES('54bb1ec9-9cfc-49cb-a0a9-864447633170',8,'Presentation',NULL,'The final piece is weighed, documented, billed, and presented at your table. You see exactly what goes into the box — the finished piece, its details, and its journey.',NULL,1);
INSERT INTO "people" ("id","name","role","since","note","portrait_id","consent_on_file","sort_order","published") VALUES('4f72ea57-2bd8-498a-8d6f-e89d849905d5','Shri Ashok Kumar Bansal','Founder (1993)',1993,'Opened the workshop in 1993 and set the standard the house still keeps. Trained eleven years under a goldsmith before that. The house continues under his sons and nephew.',NULL,0,0,0);
INSERT INTO "people" ("id","name","role","since","note","portrait_id","consent_on_file","sort_order","published") VALUES('c1501cd4-b34b-4253-9b0c-2c61435ebf17','Chetan Bansal','Manufacturing and quality',2011,'Signs off every piece before it leaves the workshop. Started at the bench, not the counter.',NULL,0,1,0);
INSERT INTO "people" ("id","name","role","since","note","portrait_id","consent_on_file","sort_order","published") VALUES('3fd2df97-de2f-4c8a-b527-c0e1f4a49953','Karan Bansal','Design and commissions',2011,'Takes most bespoke consultations and draws the first sketch himself.',NULL,0,2,0);
INSERT INTO "people" ("id","name","role","since","note","portrait_id","consent_on_file","sort_order","published") VALUES('16e4c0c2-fca0-41a0-83cc-24bcb3531a66','Rajeev Bansal','Stone sourcing and certification',2014,'Buys coloured stones and diamonds in person and matches every certificate to the piece it goes into.',NULL,0,3,0);
INSERT INTO "people" ("id","name","role","since","note","portrait_id","consent_on_file","sort_order","published") VALUES('ddcfca6e-4cb6-4b15-ae93-342d958bf392','[TK] Head goldsmith','Head goldsmith',NULL,'PLACEHOLDER. Naming the senior bench staff is one of the strongest trust signals available and almost nobody in the category does it.',NULL,0,4,0);
